insert into public.products (id, slug, name, description, price_inr, category_id, style, slogan, colors, featured, created_at) values
  ('2f7d0121-2c05-5941-a521-0397d8187aa4', 'the-quiet-type', 'The Quiet Type', 'A soft-spoken statement tee for people who say more by saying less. Heavyweight cotton with a clean chest print.', 599, '35eb5291-0516-59e1-a5dd-89cfd8053e1a', 'Typographic', 'the quiet type', '[{"name":"Cream","hex":"#EDE6D6"},{"name":"Charcoal","hex":"#252820"},{"name":"Olive","hex":"#667052"}]'::jsonb, true, '2026-10-28'),
  ('57d3361b-8280-58b6-a410-50ab0fa07c93', 'grounded', 'Grounded', 'Earthy and calm. A small centred mark on a relaxed everyday fit.', 549, '72eea6ca-6e05-5a78-af52-b6fcee565189', 'Minimal', 'grounded', '[{"name":"Olive","hex":"#667052"},{"name":"Sand","hex":"#D8CDB6"},{"name":"Charcoal","hex":"#252820"}]'::jsonb, true, '2026-10-12'),
  ('f0100cda-74ad-5b83-a091-1755e8af5711', 'off-script', 'Off Script', 'For the ones who skip the plan. Bold back print, understated front.', 649, '4b2d07ca-203a-5ff5-a3e1-5331bd478c34', 'Illustrated', 'off script', '[{"name":"Charcoal","hex":"#252820"},{"name":"Terracotta","hex":"#B87958"},{"name":"Cream","hex":"#EDE6D6"}]'::jsonb, true, '2026-11-05'),
  ('25911090-f5dd-58a2-a80a-3ca014f820d6', 'everyday-essential', 'Everyday Essential', 'The plain tee, done properly. Soft, durable and made to be worn on repeat.', 499, 'd859b9cc-aff3-5fd2-ae0e-d1dcadaffd4a', 'Essentials', 'essential', '[{"name":"Ivory","hex":"#FFFDF8"},{"name":"Charcoal","hex":"#252820"},{"name":"Olive","hex":"#667052"},{"name":"Terracotta","hex":"#B87958"}]'::jsonb, false, '2026-09-20'),
  ('b2a10933-d518-596b-a6e2-e6d72106114b', 'slow-living', 'Slow Living', 'A reminder to take the long way home. Tonal print on a washed finish.', 599, '35eb5291-0516-59e1-a5dd-89cfd8053e1a', 'Typographic', 'slow living', '[{"name":"Sand","hex":"#D8CDB6"},{"name":"Olive","hex":"#667052"},{"name":"Cream","hex":"#EDE6D6"}]'::jsonb, true, '2026-11-12'),
  ('2784844c-3902-5273-a16a-285569f161a0', 'unfiltered', 'Unfiltered', 'Loud ideas, quiet colours. Our boldest graphic, in a premium oversized cut.', 699, '4b2d07ca-203a-5ff5-a3e1-5331bd478c34', 'Illustrated', 'unfiltered', '[{"name":"Terracotta","hex":"#B87958"},{"name":"Charcoal","hex":"#252820"},{"name":"Ivory","hex":"#FFFDF8"}]'::jsonb, false, '2026-11-16')
